package com.campuslostfound.model;
public class Claim { private final int id,itemId,claimantId; private final String message; private ClaimStatus status; public Claim(int id,int itemId,int claimantId,String message,ClaimStatus status){this.id=id;this.itemId=itemId;this.claimantId=claimantId;this.message=message;this.status=status;} public int getId(){return id;} public int getItemId(){return itemId;} public int getClaimantId(){return claimantId;} public String getMessage(){return message;} public ClaimStatus getStatus(){return status;} public void setStatus(ClaimStatus s){status=s;} }
